import { useState } from 'react';
import { JxInput, JxButton, JxToast, JxForm, JxFormField } from '@jinx-ui/react';

export default function NewsletterSubscribeForm() {
  const [email, setEmail] = useState('');
  const [showToast, setShowToast] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!email) return;

    setEmail('');
    setShowToast(true);
  };

  return (
    <div className="jx-stack jx-stack-md" style={{ position: 'relative' }}>
      <JxForm onSubmit={handleSubmit} className="jx-stack jx-stack-sm">
        <JxFormField label="Email">
          <JxInput
            type="email"
            name="email"
            placeholder="you@example.com"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
          />
        </JxFormField>
        <JxButton type="submit" variant="primary">
          Подписаться
        </JxButton>
      </JxForm>

      {showToast && (
        <JxToast
          variant="success"
          title="Готово"
          description="Письмо отправлено на вашу почту."
          position="top-right"
          onClose={() => setShowToast(false)}
        />
      )}
    </div>
  );
}

